class F90CodeLine(CodeLine):
    """Plain Text version of a StatementLine"""


class F90CommentLine(CommentLine):
    """Plain Text version of a CommentLine"""

    COMMENT_PREFIX = "! "

    # some_aux_variable = LibRoutineLocalVariable("testvar")


class F90LoopContainer(LoopContainer):
    """Plain Text version of a DefinitionContainer"""

    INDENT_BODY = True


class F90DefinitionContainer(DefinitionContainer):
    """Plain Text version of a DefinitionContainer"""

    INDENT_BODY = False


class F90RoutineContainer(RoutineContainer):
    """Plain Text version of a RoutineDefinition"""

    # def __init__(self, name, *, context, **buildargs):
    #     return RoutineContainer.__init__

    INDENT_BODY = True

    def generate_head_containers(self, **_):
        call_args = self.get_call_arguments()
        yield self.codeline_from_text(
            f"SUBROUTINE {self.name}({', '.join(call_args)})"
        )

    def generate_foot_containers(self, **_):
        yield self.codeline_from_text(f"END SUBROUTINE {self.name}")


class F90LibraryContainer(LibraryContainer):
    """Plain Text version of a RoutineDefinition"""

    INDENT_BODY = True

    def __init__(self, name, *, context, **buildargs):
        # print("f90lib init")
        super().__init__(name, context=context, **buildargs)

    def generate_head_containers(self, **_):
        yield self.codeline_from_text(f"MODULE {self.name}")

    def generate_foot_containers(self, **_):
        yield self.codeline_from_text(f"END MODULE {self.name}")

    def generate_preamble_containers(self, **_):
        yield self.codeline_from_text("implicit none")
        yield from super().generate_preamble_containers()
        yield self.codeline_from_text("contains")


class F90LibRoutineVariable(LibRoutineVariable):
    """LibRoutineVariable F90 Base class"""

    _intent = None

    def lookup_intent(self, intent):
        if intent is None:
            return None
        if intent == "RO":
            return "IN"
        if intent == "WO":
            return "OUT"
        if intent == "RW":
            return "INOUT"
        raise ValueError(f"Unknown intent: {intent}")

    def get_definition_lines(self) -> str:
        """create the line that defines the variable"""
        intent_str = ""
        dimension_str = ""
        intent = self.lookup_intent(type(self)._intent)
        if intent:
            intent_str = f", intent({intent})"
        if not self.is_scalar:
            dimension_str = f", dimension({self._size})"
        yield f"{self.lookup_dtype(self._dtype)}{intent_str}{dimension_str} :: {self._name}"

    def lookup_dtype(self, dtype):
        match dtype:
            case "f64":
                return "double precision"
            case "f32":
                return "real"
            case "i64":
                return "integer(8)"
            case "i32":
                return "integer"
        raise ValueError(f"Unknown dtype: {dtype}")


class F90InputVariable(F90LibRoutineVariable, LibRoutineInputVariable):
    _intent = "RO"


class F90OutputVariable(F90LibRoutineVariable, LibRoutineOutputVariable):
    _intent = "WO"


class F90InOutVariable(F90LibRoutineVariable, LibRoutineInOutVariable):
    _intent = "RW"


class F90Constant(F90LibRoutineVariable, LibRoutineConstant):
    def get_definition_lines(self) -> str:
        """create the line that defines the variable"""
        dimension_str = ""
        if not self.is_scalar:
            dimension_str = f", dimension({self._size})"
        if self.is_scalar:
            yield f"{self.lookup_dtype(self._dtype)}, parameter :: {self._name} = {self.value}"
            return
        line = f"{self.lookup_dtype(self._dtype)}, parameter :: {self._name}({self.size}) = "
        prefix = "(/"
        suffix = "/)"
        conv = float
        if self.dtype[0] == "i":
            conv = int
        for line in multiline_iterable(
            [conv(value) for value in self.values],
            separator=", ",
            max_line_length=100,
            indent="",
            extra_indent="  ",
            linebreak=" &",
            prefix=line + prefix,
            suffix=suffix,
            prefix_suffix_lines=True,
        ):
            yield line


